table{width:100%;border-collapse:collapse;font-size:13px}
thead th{text-align:left;font-size:11px;font-weight:700;text-transform:uppercase;letter-spacing:.6px;color:var(--muted);padding:10px 12px;border-bottom:1.5px solid var(--border);background:#FAFBFE;position:sticky;top:0;z-index:1}
tbody td{padding:9px 12px;border-bottom:1px solid var(--border);vertical-align:middle}
tbody tr:hover{background:#F8FAFE}
.right{text-align:right;font-variant-numeric:tabular-nums}
.bold-val{font-weight:700;color:var(--green)}
/* P&L table */
.pl-table{width:100%;border-collapse:collapse;font-size:13px}
.pl-table td{padding:9px 12px;border-bottom:1px solid var(--border)}
