/* funnel */
.funnel{display:flex;flex-direction:column;gap:6px;align-items:center;padding:8px 0}
.funnel-step{border-radius:8px;display:flex;justify-content:space-between;align-items:center;padding:10px 18px;color:#fff;font-weight:600;font-size:13px;transition:transform .15s;cursor:default}
