// ── seguimiento semanal KPI ───────────────────────────────────────────────────
(function() {
  const tbody = document.getElementById('tbody-kpi-hist');
  if(!tbody || !KPI_HIST.length) return;
  // mostrar en orden inverso (más reciente primero)
  const hist = [...KPI_HIST].reverse();
  tbody.innerHTML = hist.map((row, i) => {
    const prev = hist[i+1];
    const delta = prev !== undefined ? row.cerrado - prev.cerrado : null;
    const deltaHtml = delta === null ? '<span style="color:var(--muted)">—</span>'
      : delta > 0 ? `<span style="color:var(--green);font-weight:700">+${delta}</span>`
      : delta < 0 ? `<span style="color:var(--red);font-weight:700">${delta}</span>`
      : '<span style="color:var(--muted)">0</span>';
    const isLatest = i === 0;
    return `<tr style="${isLatest ? 'background:#F0FFF5;font-weight:600' : ''}">
      <td>${row.fecha}${isLatest ? ' <span class="badge badge-green" style="font-size:10px">actual</span>' : ''}</td>
      <td class="right">${row.total}</td>
      <td class="right" style="color:#9E9E9E">${row.lead}</td>
      <td class="right" style="color:#42A5F5">${row.en_contacto}</td>
      <td class="right" style="color:#B8860B">${row.cotizado}</td>
      <td class="right" style="color:var(--green);font-weight:700">${row.cerrado}</td>
      <td class="right" style="color:var(--red)">${row.descartado}</td>
      <td class="right">${deltaHtml}</td>
    </tr>`;
  }).join('');
})();

// ── pie chart motivos descarte (reactivo al periodo) ─────────────────────────
const MOTIVOS_LABELS = ["Preexistencia","Costos","Cambio de cobertura reciente",
                        "No le interesa el producto","No contacto"];
const MOTIVOS_COLORS = ['#EF5350','#FDD835','#42A5F5','#66BB6A','#AB47BC'];
let chartMotivos = null;

function renderMotivos(rows) {
  const desc = rows.filter(c=>c.estado==='Descartado');
  const vals = MOTIVOS_LABELS.map(lbl => desc.filter(c=>c.motivo===lbl).length);
  const total = vals.reduce((a,b)=>a+b,0);

  const titleEl = document.getElementById('motivos-title');
  if(titleEl) titleEl.textContent = `Motivos de Descarte — ${desc.length} descartados`;

  const canvas = document.getElementById('chartMotivos');
  if(canvas) {
    if(chartMotivos) {
      chartMotivos.data.datasets[0].data = vals;
      chartMotivos.update();
    } else {
      chartMotivos = new Chart(canvas, {
        type: 'doughnut',
        data: { labels: MOTIVOS_LABELS, datasets: [{
          data: vals, backgroundColor: MOTIVOS_COLORS, borderWidth: 2, borderColor: '#fff'
        }] },
        options: {
          responsive: true, maintainAspectRatio: false,
          plugins: {
            legend: { position: 'bottom', labels: { font: { size: 11 }, boxWidth: 12, padding: 10 } },
            tooltip: { callbacks: { label: ctx => ` ${ctx.label}: ${ctx.raw} (${total?(ctx.raw/total*100).toFixed(1):0}%)` } }
          }
        }
      });
    }
  }

  const tbody = document.getElementById('motivos-tabla');
  if(tbody) {
    tbody.innerHTML = MOTIVOS_LABELS.map((lbl,i) => {
      const v = vals[i];
      const pct = total ? (v/total*100).toFixed(1) : '0.0';
      const dot = `<span style="display:inline-block;width:10px;height:10px;border-radius:50%;background:${MOTIVOS_COLORS[i]};margin-right:6px"></span>`;
      return `<tr><td>${dot}${lbl}</td><td class="right"><strong>${v}</strong></td><td class="right" style="color:var(--muted)">${pct}%</td></tr>`;
    }).join('');
  }
}
renderMotivos(CONTACTOS);

