function filtrarSeguimiento() {
  const fa=document.getElementById('fa-asesora').value;
  const fe=document.getElementById('fa-estado').value;
  const fc=document.getElementById('fa-canal').value;
  const fm=document.getElementById('fa-mes').value;
  const fp=document.getElementById('fa-plan').value;
  const fb=document.getElementById('fa-buscar').value.toLowerCase();
  const rows=CONTACTOS.filter(c=>
    (!fa||c.comercial===fa)&&(!fe||c.estado===fe)&&(!fc||c.canal===fc)&&
    (!fm||c.mes===fm)&&(!fp||c.plan===fp)&&(!fb||c.nombre.toLowerCase().includes(fb)));
  document.getElementById('tbody-seguimiento').innerHTML=rows.length?rows.map(c=>`
    <tr>
      <td>${c.nombre}</td><td>${c.comercial}</td><td>${tagC(c.canal)}</td>
      <td>${badgeE(c.estado)}</td><td>${c.plan||'—'}</td><td>${c.tipo||'—'}</td>
      <td>${c.grupo||'—'}</td><td class="right">${fmtArs(c.cuota)}</td>
      <td>${c.mes||'—'}</td><td>${c.lugar||'—'}</td>
      <td style="max-width:200px;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;font-size:11px;color:var(--muted)">${c.obs||''}</td>
    </tr>`).join('')
    :'<tr><td colspan="11" style="text-align:center;color:var(--muted);padding:20px">Sin resultados</td></tr>';
  document.getElementById('count-seg').textContent=rows.length+' contacto'+(rows.length!==1?'s':'');
}

// ── costos P&L ─────────────────────────────────────────────────────────────────
let costosPeriodo = 'todos';
function setCostosPeriodo(p, btn) {
  costosPeriodo = p;
  document.querySelectorAll('#costos-period-btns .period-btn').forEach(b=>b.classList.remove('active'));
  btn.classList.add('active');
  renderCostos();
}

function plRow(concepto, valor, clase='') {
  const valStr = typeof valor === 'number' ? fmtArs(valor) : valor;
  const negClass = typeof valor === 'number' && valor < 0 ? ' neg' : '';
  return `<tr class="${clase}"><td>${concepto}</td><td class="val${negClass}">${valStr}</td></tr>`;
}

function renderCostos() {
  const d = COSTOS_DATA[costosPeriodo] || COSTOS_DATA['todos'];
  const lbl = costosPeriodo==='todos' ? 'Todos los periodos' : costosPeriodo;
  document.getElementById('costos-period-label').textContent = `Estado de Resultado Comercial — ${lbl}`;

  let html = '';
  const descuentoGF = d.descuento_gf || 0;
  html += plRow('INGRESOS','','pl-header');
  if (descuentoGF > 0) {
    html += plRow('Cuotas (precio individual equiv.)', d.ingresos + descuentoGF, 'pl-sub');
    html += plRow('Descuento por Grupo Familiar', -descuentoGF, 'pl-sub');
  } else {
    html += plRow('Cuotas mensuales activas', d.ingresos, 'pl-sub');
  }
  html += plRow('Total Ingresos', d.ingresos, 'pl-subtotal');

  html += plRow('COSTOS COMERCIALES','','pl-header');

  // Comisiones por asesora
  COMERCIALES.forEach(com => {
    const a = d.asesoras[com];
    if(a.comision_fuera) html += plRow(`Comisión ${com} — Terreno (${a.fuera_cap} cáp.)`, -a.comision_fuera, 'pl-sub');
    if(a.comision_dentro) html += plRow(`Comisión ${com} — OSPIF (${a.dentro_cap} cáp.)`, -a.comision_dentro, 'pl-sub');
    if(!a.comision_fuera && !a.comision_dentro) html += plRow(`Comisión ${com}`, 0, 'pl-sub');
  });
  html += plRow('Total Comisiones', -d.total_comision, 'pl-subtotal');
  const mktTotal = costosPeriodo==='todos'
    ? MARKETING.reduce((s,m)=>s+m.gasto,0)
    : (MARKETING.find(m=>m.mes===costosPeriodo)||{gasto:0}).gasto;
  html += plRow('Marketing / Publicidad', -mktTotal, 'pl-sub');
  html += plRow('Otros Gastos', '— pendiente carga —', 'pl-sub');
  const totalCostos = d.total_comision + mktTotal;
  html += plRow('Total Costos Comerciales', -totalCostos, 'pl-subtotal');

  const res = d.ingresos - totalCostos;
  html += `<tr class="pl-total"><td>RESULTADO COMERCIAL</td><td class="val">${fmtArs(res)}</td></tr>`;

  document.getElementById('costos-pl-body').innerHTML = html;

  // detalle asesoras
  let detHTML = '<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr>'
    +'<th style="text-align:left;padding:8px;border-bottom:1px solid var(--border)">Asesora</th>'
    +'<th style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">Terreno</th>'
    +'<th style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">OSPIF</th>'
    +'<th style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">Total</th>'
    +'</tr></thead><tbody>';
  COMERCIALES.forEach(com=>{
    const a=d.asesoras[com];
    detHTML+=`<tr><td style="padding:8px;border-bottom:1px solid var(--border)">${com}</td>`
      +`<td style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">${fmtArs(a.comision_fuera)}</td>`
      +`<td style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">${fmtArs(a.comision_dentro)}</td>`
      +`<td style="text-align:right;padding:8px;border-bottom:1px solid var(--border);font-weight:700">${fmtArs(a.total)}</td></tr>`;
  });
  detHTML+='</tbody></table>';
  document.getElementById('costos-asesoras-detalle').innerHTML=detHTML;

  // marketing filtrado por periodo
  const mkt = costosPeriodo==='todos' ? MARKETING : MARKETING.filter(m=>m.mes===costosPeriodo);
  const mktEl = document.getElementById('costos-marketing');
  if(mktEl) {
    if(!mkt.length) {
      mktEl.innerHTML='<div class="note-placeholder" style="margin-top:0"><strong>&#128203; Marketing</strong> &mdash; Sin datos Meta Ads para este período</div>';
    } else {
      const trs = mkt.map(m =>
        `<tr><td style="padding:8px;border-bottom:1px solid var(--border)">${m.mes}</td>`
        +`<td style="text-align:right;padding:8px;border-bottom:1px solid var(--border);font-weight:700;color:var(--red)">${fmtArs(m.gasto)}</td>`
        +`<td style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">${m.alcance.toLocaleString('es-AR')}</td>`
        +`<td style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">${m.impresiones.toLocaleString('es-AR')}</td></tr>`
      ).join('');
      mktEl.innerHTML='<div class="panel" style="margin-top:0"><div class="panel-title">Marketing Meta Ads</div>'
        +'<table style="width:100%;border-collapse:collapse;font-size:13px"><thead><tr>'
        +'<th style="text-align:left;padding:8px;border-bottom:1px solid var(--border)">Mes</th>'
        +'<th style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">Gasto</th>'
        +'<th style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">Alcance</th>'
        +'<th style="text-align:right;padding:8px;border-bottom:1px solid var(--border)">Impresiones</th>'
        +`</tr></thead><tbody>${trs}</tbody></table></div>`;
    }
  }
}

// ── cobros ────────────────────────────────────────────────────────────────────
function filtrarCobros() {
  const ft = document.getElementById('fc-tipo').value;
  const fp = document.getElementById('fc-plan').value;
  const fe = document.getElementById('fc-estado').value;
  const fb = document.getElementById('fc-buscar').value.toLowerCase();
  const rows = DETALLE_C.filter(a =>
    (!ft || a.tipo === ft) &&
    (!fp || a.plan === fp) &&
    (!fe || (fe==='si' ? a.pagado : !a.pagado)) &&
    (!fb || a.nombre.toLowerCase().includes(fb))
  );
  const tbody = document.getElementById('tbody-cobros');
  if(!tbody) return;
  tbody.innerHTML = rows.length ? rows.map(a => {
    const estadoBadge = a.bonificado
      ? '<span class="badge badge-grey">★ Bonificado</span>'
      : a.pagado
        ? '<span class="badge badge-green">✓ Pagó</span>'
        : '<span class="badge badge-red">✗ Sin pago</span>';
    const medio = a.pago ? a.pago.medio : '—';
    const rowBg = a.bonificado ? 'background:#F8F9FA' : a.pagado ? '' : 'background:#FFF5F5';
    const cuotaDisplay = a.bonificado ? '<span style="color:var(--muted);font-style:italic">Bonificado</span>' : fmtArs(a.cuota_est);
    return `<tr style="${rowBg}">
      <td>${a.nombre}</td>
      <td><span class="badge badge-blue">${a.plan}</span></td>
      <td style="font-size:11px">${a.delegacion}</td>
      <td style="font-size:11px">${a.tipo}</td>
      <td class="right">${cuotaDisplay}</td>
      <td>${estadoBadge}</td>
      <td class="right">${a.cobrado ? fmtArs(a.cobrado) : '—'}</td>
      <td style="font-size:11px;color:var(--muted)">${medio}</td>
    </tr>`;
  }).join('') : '<tr><td colspan="8" style="text-align:center;color:var(--muted);padding:20px">Sin resultados</td></tr>';
  document.getElementById('count-cobros').textContent = rows.length + ' afiliado' + (rows.length!==1?'s':'');
}

function renderCobrosTabla() {
  const tbody = document.getElementById('cobros-tabla-meses');
  if(!tbody || !COBROS_TABLA.length) return;
  tbody.innerHTML = COBROS_TABLA.map(m => {
    const difClass = m.diferencia >= 0 ? 'pos' : 'neg';
    return `<tr>
      <td><strong>${m.mes}</strong></td>
      <td class="right">${fmtArs(m.proyectado)}</td>
      <td class="right bold-val">${fmtArs(m.cobrado_bruto)}</td>
      <td class="right">${fmtArs(m.cobrado_neto)}</td>
      <td class="right ${difClass}">${fmtArs(m.diferencia)}</td>
      <td class="right">${m.pct}%</td>
      <td class="right">${m.count}</td>
    </tr>`;
  }).join('');
}

// ── padrón tab ────────────────────────────────────────────────────────────────
function filtrarPadron() {
  const ft = document.getElementById('pp-tipo').value;
  const fp = document.getElementById('pp-plan').value;
  const fr = document.getElementById('pp-rol').value;
  const fd = document.getElementById('pp-deleg').value;
  const fb = document.getElementById('pp-buscar').value.toLowerCase();
  const rows = PADRON_DATA.filter(a =>
    (!ft || a.tipo === ft) &&
    (!fp || a.plan === fp) &&
    (!fr || a.rol  === fr) &&
    (!fd || a.delegacion === fd) &&
    (!fb || a.nombre.toLowerCase().includes(fb))
  );
  const tbody = document.getElementById('tbody-padron');
  if(!tbody) return;
  tbody.innerHTML = rows.length ? rows.map(a => {
    const tipoBadge = a.tipo==='COMERCIAL'
      ? '<span class="badge badge-green">COMERCIAL</span>'
      : a.tipo==='PLAN EMPLEADO'
        ? '<span class="badge badge-yellow">PLAN EMP.</span>'
        : '<span class="badge badge-grey">HISTÓRICO</span>';
    const rolBadge = a.rol==='Adherente'
      ? '<span style="color:var(--muted);font-size:11px">Adherente</span>'
      : a.rol==='Plan Empleado'
        ? '<span style="color:#B8860B;font-size:11px">Plan Emp.</span>'
        : '<strong style="font-size:11px">Titular</strong>';
    const cuil_t = (a.cuil_titular && a.cuil_titular !== a.cuil)
      ? `<span style="font-size:11px;color:var(--muted)">${a.cuil_titular}</span>` : '—';
    return `<tr>
      <td>${a.nombre}</td>
      <td style="font-size:11px;font-variant-numeric:tabular-nums">${a.cuil||'—'}</td>
      <td><span class="badge badge-blue">${a.plan}</span></td>
      <td>${tipoBadge}</td><td>${rolBadge}</td>
      <td style="font-size:11px">${a.delegacion}</td>
      <td>${cuil_t}</td>
    </tr>`;
  }).join('') : '<tr><td colspan="7" style="text-align:center;color:var(--muted);padding:20px">Sin resultados</td></tr>';
  document.getElementById('count-padron').textContent = rows.length + ' afiliado' + (rows.length!==1?'s':'');
}

function initPadronKpis() {
  const kpiEl = document.getElementById('padron-kpis');
  if(!kpiEl) return;
  const hist = PADRON_DATA.filter(a=>a.tipo==='HISTORICO').length;
  const com  = PADRON_DATA.filter(a=>a.tipo==='COMERCIAL').length;
  const pe   = PADRON_DATA.filter(a=>a.tipo==='PLAN EMPLEADO').length;
  const tit  = PADRON_DATA.filter(a=>a.rol==='Titular').length;
  const adh  = PADRON_DATA.filter(a=>a.rol==='Adherente').length;
  const kpis = [
    ['Total Afiliados', PADRON_DATA.length, '', 'blue'],
    ['Titulares',  tit,  '', ''],
    ['Adherentes', adh,  '', 'cyan'],
    ['Histórico',  hist, 'OSPIF base', ''],
    ['COMERCIAL',  com,  'Ventas + GF', ''],
    ['Plan Empleado', pe, 'Bonificados', 'yellow'],
  ];
  kpiEl.innerHTML = kpis.map(([lbl,val,meta,cls])=>
    `<div class="kpi-card ${cls}">
      <div class="kpi-label">${lbl}</div>
      <div class="kpi-value">${val}</div>
      ${meta ? `<div class="kpi-meta">${meta}</div>` : ''}
    </div>`).join('');
}

// ── init ──────────────────────────────────────────────────────────────────────
recalcInforme();
filtrarSeguimiento();
renderCostos();
filtrarCobros();
renderCobrosTabla();
initPadronKpis();
filtrarPadron();
document.getElementById('period-bar-informe').style.display='flex';
</script>
</body>
</html>
